_lang = "en"


def set_lang(code: str):
    global _lang
    _lang = code if code in dict(LANGS) else "en"


def get_lang() -> str:
    return _lang


def tr(key: str, **kw) -> str:
    text = TR.get(_lang, {}).get(key) or EN.get(key, key)
    try:
        return text.format(**kw) if kw else text
    except (KeyError, IndexError):
        return text
